import json,sys,inspect,types,dataclasses,importlib,pkgutil
from pathlib import Path
import pytest,coverage
from btc_predictor.research_backtest import input_census as ic
census=ic.discover_decision_path()
mods=sorted({p.rsplit('.',1)[0] for p in []})
files=sorted({r.source.rsplit(':',1)[0] for r in [*census.callables.values(),*census.types.values()]})
name=sys.argv[1]
cov=coverage.Coverage(branch=True,data_file=f'/tmp/rbt002-rereview/.coverage-{name}',source=[str(Path('btc_predictor').resolve())])
functions=set();classes=set();entered=set();active=set()
roots=set(census.root_paths)
def profile(frame,event,arg):
    if event=='call':
        path=f"{frame.f_globals.get('__name__')}.{frame.f_code.co_qualname}"
        if path in roots:entered.add(path);active.add(id(frame))
        if active:
            code=frame.f_code
            if code.co_name=='__init__':
                obj=frame.f_locals.get('self')
                if obj is not None and dataclasses.is_dataclass(obj) and ic.in_scope_module(type(obj).__module__):classes.add(ic.owner_path(type(obj)))
            if ic._is_package_source(code.co_filename) and ic.in_scope_module(frame.f_globals.get('__name__')):functions.add(path)
    elif event=='return':active.discard(id(frame))
cov.start();sys.setprofile(profile)
if name=='fixtures':
    count=0
    for info in sorted(pkgutil.iter_modules(importlib.import_module('btc_predictor.tests').__path__),key=lambda i:i.name):
        if info.name.startswith('test_research_backtest_census_trace_g'):
            mod=importlib.import_module(f'btc_predictor.tests.{info.name}')
            for root,thunks in mod.FIXTURES.items():
                for thunk in thunks:thunk();count+=1
    result=0
else:
    args=json.loads(Path('/tmp/rbt002-rereview/owner-test-modules.json').read_text())
    result=pytest.main(['-q',*args]);count=None
sys.setprofile(None);cov.stop();cov.save()
cov.json_report(outfile=f'/tmp/rbt002-rereview/coverage-{name}.json', include=[str(Path(f).resolve()) for f in files])
out={'fixture_runs':count,'pytest_exit':int(result),'entered_roots':len(entered),'functions':len(functions),'constructed_types':len(classes),'uncovered':ic.uncovered_traced(census,ic.TracedCalls(frozenset(functions),frozenset(classes))),'source_files':files}
Path(f'/tmp/rbt002-rereview/trace-{name}.json').write_text(json.dumps(out,indent=2)+'\n')
print(json.dumps(out,indent=2));raise SystemExit(result)

