import dataclasses,sys,time
from btc_predictor.research_backtest import coverage as co,input_census as ic
c=ic.discover_decision_path();start=time.monotonic();passed=0
for path,r in c.types.items():
 if r.kind==ic.TYPE_CLASS:continue
 mod,name=path.rsplit('.',1);cls=getattr(sys.modules[mod],name)
 if r.kind==ic.TYPE_DATACLASS:
  fixture=dataclasses.make_dataclass('FieldSchemaFixture',[('independent_added_field',object,dataclasses.field(default=None))])
  original=cls.__dataclass_fields__
  setattr(cls, 'independent_added_field', None)
  cls.__dataclass_fields__={**original,'independent_added_field':fixture.__dataclass_fields__['independent_added_field']}
  restore=lambda: setattr(cls,'__dataclass_fields__',original)
 else:
  original=cls.__annotations__;cls.__annotations__={**original,'independent_added_field':object}
  restore=lambda: setattr(cls,'__annotations__',original)
 try:
  co.enumerate_input_surface()
  raise AssertionError('live field mutation accepted: '+path)
 except co.InputSurfaceError as e:
  assert e.code=='UNCLASSIFIED_FIELD' and 'independent_added_field' in str(e),(path,e)
  passed+=1
 finally:
  restore()
  if r.kind==ic.TYPE_DATACLASS:delattr(cls,'independent_added_field')
 if passed%25==0:print('live field schemas refused',passed,'seconds',round(time.monotonic()-start,1),flush=True)
assert passed==157
print('live field schemas refused',passed,'seconds',round(time.monotonic()-start,1),flush=True)
